parameters.jsCode:
// Meta posts inbound messages and status updates (sent, delivered, read)
// to the same URL, and can batch several of them in one request.
// Keep only inbound text messages, one item each. No items stops the run.
const out = [];
for (const item of $input.all()) {
  for (const entry of item.json.body?.entry ?? []) {
    for (const change of entry.changes ?? []) {
      const value = change.value ?? {};
      const names = Object.fromEntries((value.contacts ?? []).map((c) => [c.wa_id, c.profile?.name ?? '']));
      for (const message of value.messages ?? []) {
        if (message.type !== 'text' || !message.text?.body) continue;
        out.push({
          json: {
            message_id: message.id,
            phone: message.from,
            name: String(names[message.from] ?? '').slice(0, 100),
            text: String(message.text.body).slice(0, 4000),
          },
        });
      }
    }
  }
}
return out;

